//! Smalltalk (Pharo, UnifiedFFI): `Azul.st` (Tonel, generated by
//! `doc/src/codegen/v2/lang_smalltalk`).
//!
//! Spellings: every C function is a class-side method of `AzulNative`
//! whose selector is the lowerCamel C symbol, further arguments keyed by
//! their parameter names (`AzulNative azCssPropertyTextColor: x`,
//! `AzulNative azPixelValueFromMetric: m value: v`, variant constructors
//! `AzulNative azLayoutWidthPx: pv`); C-like enums are
//! `FFIExternalEnumeration`s (`AzLayoutDisplay Flex`); structs are
//! `FFIExternalStructure`s filled by a cascade
//! (`(AzColorU new r: 255; g: 0; b: 0; a: 255; yourself)`). A Vec is copied
//! from an `FFIExternalArray` (`vec:of:items:` below), a String from an
//! external UTF-8 buffer (`str:`).
//!
//! Limitation: the bindings define no class for the `CssPropertyValue<T>`
//! aliases (`AzLayoutWidthValue`, ...), so neither they nor a hand-built
//! `CssProperty` (whose variants carry them) can be written.
//!
//! DOM export (class `AzulUi`): a builder method is the `AzulNative` send
//! with the receiver first (`AzulNative azDomWithChild: dom child: c`),
//! one keyword per line when it nests; an item with parameters is a keyword
//! method (`renderCardTitle: title text: text ..`) plus a unary one with the
//! component's defaults (`renderCard`); a parameter is a Smalltalk string
//! converted by `self str:` where it is used, a joined string `self str:
//! 'by ' , author`. A component instance calls its item with Smalltalk
//! strings (`self renderBadgeText: tag`). The binding
//! makes no C callbacks at all (no
//! `FFICallback` wrappers, no host invoker): an app builds its UI once
//! instead of opening a window, and no library is registered
//! ([`NO_CALLBACKS`]).

use alloc::{
    format,
    string::{String, ToString},
    vec,
    vec::Vec,
};

use crate::codegen::{
    doc::{render, Doc},
    ir::{capitalize, lower_first, snake_to_lower_camel, EnumShape, Expr, Ident, Item, Module, Prim},
    lang::{
        call_param_names,
        dom::{one_line, registration_note},
        expr_doc, item_comments, item_doc, module_any, variant_ctor_method, ConcatPart,
        ExprSyntax, MethodLayout,
    },
    CodegenBackend, GeneratedFile,
};

/// The Smalltalk printer.
#[derive(Debug, Copy, Clone, Default)]
pub struct Smalltalk;

/// Why a Smalltalk app cannot open its window and no library is registered.
const NO_CALLBACKS: &str = "the Smalltalk binding makes no C callbacks (it generates no \
                            FFICallback wrappers and has no host invoker), so no Smalltalk block \
                            can be the layout callback or a component's render function";

/// The C parameter name of a builder method's argument: its keyword after
/// the receiver (`azDomWithChild: dom child: c`, as `lang_smalltalk` names
/// the selector parts after the C parameters).
fn method_param_name(method: &str) -> &'static str {
    match method {
        "with_child" => "child",
        "with_css" => "style",
        "with_class" => "class",
        "with_id" => "id",
        _ => "value",
    }
}

/// A parameter's Smalltalk name (a pseudo-variable gets `Arg`).
fn st_param(name: &Ident) -> String {
    let s = name.lower_camel();
    if ["self", "super", "true", "false", "nil", "thisContext"].contains(&s.as_str()) {
        format!("{s}Arg")
    } else {
        s
    }
}

/// The class of a DOM export (`AzulUi`) or of styles (`AzulStyles`).
fn class_name(m: &Module) -> &'static str {
    if m.is_dom() {
        "AzulUi"
    } else {
        "AzulStyles"
    }
}

/// The selector base of C symbol `c_name` (`snake_to_lower_camel` of
/// `lang_smalltalk/mod.rs`): `AzCssProperty_textColor` -> `azCssPropertyTextColor`.
fn selector(c_name: &str) -> String {
    lower_first(&snake_to_lower_camel(c_name))
}

/// A message argument: parenthesized unless it is a literal or a name.
fn arg(d: Doc) -> Doc {
    if d.flat().contains(' ') && !d.flat().starts_with(SELF_PARENTHESIZED.trim_end()) {
        Doc::cat(vec![Doc::text("("), d, Doc::text(")")])
    } else {
        d
    }
}

/// How a builder-method send starts: it brings its own parentheses (see
/// `method`), so [`arg`] does not add more.
const SELF_PARENTHESIZED: &str = "(AzulNative ";

/// `AzulNative sel: a key: b`.
fn send(c_name: &str, keys: &[&str], args: Vec<Doc>) -> Doc {
    let base = selector(c_name);
    if args.is_empty() {
        return Doc::text(format!("AzulNative {base}"));
    }
    let mut parts = vec![Doc::text("AzulNative ")];
    for (i, a) in args.into_iter().enumerate() {
        let key = if i == 0 {
            base.clone()
        } else {
            keys.get(i).map_or_else(|| format!("arg{i}"), |k| (*k).to_string())
        };
        if i > 0 {
            parts.push(Doc::text(" "));
        }
        parts.push(Doc::text(format!("{key}: ")));
        parts.push(arg(a));
    }
    Doc::cat(parts)
}

fn st_string(s: &str) -> String {
    format!("'{}'", s.replace('\'', "''"))
}

impl ExprSyntax for Smalltalk {
    fn int(&self, value: i128, _ty: Prim) -> String {
        value.to_string()
    }

    fn float(&self, text: &str, _ty: Prim) -> String {
        match text {
            "nan" => "Float nan".to_string(),
            "inf" => "Float infinity".to_string(),
            "-inf" => "Float negativeInfinity".to_string(),
            _ => text.to_string(),
        }
    }

    fn boolean(&self, b: bool) -> String {
        b.to_string()
    }

    fn string(&self, s: &str) -> Doc {
        Doc::text(format!("self str: {}", st_string(s)))
    }

    fn call(&self, class: &str, method: &str, args: Vec<Doc>, _broken: bool) -> Doc {
        send(
            &format!("Az{class}_{}", snake_to_lower_camel(method)),
            call_param_names(class, method),
            args,
        )
    }

    fn variant(&self, ty: &str, shape: EnumShape, variant: &str, args: Vec<Doc>, _broken: bool) -> Doc {
        match shape {
            EnumShape::CLike => Doc::text(format!("Az{ty} {variant}")),
            EnumShape::Tagged => send(&format!("Az{ty}_{}", variant_ctor_method(variant)), &[], args),
            // unreachable: `limitation` rejects hand-built unions
            EnumShape::TaggedShadowed | EnumShape::Generic { .. } => {
                Doc::text(format!("self error: 'cannot build {ty} {variant}'"))
            }
        }
    }

    fn strukt(&self, ty: &str, fields: Vec<(String, Doc)>, _broken: bool) -> Doc {
        let mut parts = vec![Doc::text(format!("Az{ty} new"))];
        for (i, (k, v)) in fields.into_iter().enumerate() {
            parts.push(Doc::text(if i == 0 {
                format!(" {k}: ")
            } else {
                format!("; {k}: ")
            }));
            parts.push(arg(v));
        }
        parts.push(Doc::text("; yourself"));
        Doc::cat(parts)
    }

    fn vec(&self, ty: &str, elem: &str, items: Vec<Doc>, broken: bool) -> Doc {
        if items.is_empty() {
            return Doc::text(format!("AzulNative {}", selector(&format!("Az{ty}_create"))));
        }
        Doc::cat(vec![
            Doc::text(format!(
                "self vec: [ :p :n | AzulNative {}: p len: n ] of: Az{elem} items: ",
                selector(&format!("Az{ty}_copyFromPtr"))
            )),
            Doc::list("{", items.into_iter().map(arg).collect(), ". ", "}", true, broken, false),
        ])
    }

    fn unsupported(&self, what: &str) -> Doc {
        Doc::text(format!("self error: {}", st_string(&format!("not expressible: {what}"))))
    }

    fn limitation(&self, e: &Expr) -> Option<String> {
        match e {
            Expr::Variant {
                ty,
                shape: EnumShape::Generic { .. } | EnumShape::TaggedShadowed,
                ..
            } => Some(format!(
                "the Smalltalk bindings define no class for `{ty}` or its CssPropertyValue<T> \
                 payload"
            )),
            _ => None,
        }
    }

    fn dom_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `AzulNative azDomWithChild: recv child: c`; a nested send puts each
    /// keyword part on a line of its own.
    fn method(&self, recv: Doc, class: &str, method: &str, args: Vec<Doc>, layout: MethodLayout) -> Doc {
        let keys = ["dom", method_param_name(method)];
        let mut all = vec![recv];
        all.extend(args);
        let base = selector(&format!("Az{class}_{}", snake_to_lower_camel(method)));
        let parts: Vec<Doc> = all
            .into_iter()
            .enumerate()
            .map(|(i, a)| {
                let key = if i == 0 {
                    base.clone()
                } else {
                    keys.get(i).map_or_else(|| format!("arg{i}"), |k| (*k).to_string())
                };
                Doc::cat(vec![Doc::text(format!("{key}: ")), arg(a)])
            })
            .collect();
        if layout.node_tall {
            Doc::list("(AzulNative", parts, "", ")", false, true, false)
        } else {
            let flat: Vec<String> = parts.iter().map(Doc::flat).collect();
            Doc::text(format!("{SELF_PARENTHESIZED}{})", flat.join(" ")))
        }
    }

    fn param(&self, name: &Ident) -> Doc {
        Doc::text(format!("self str: {}", st_param(name)))
    }

    /// `self str: 'by ' , author`.
    fn concat(&self, parts: &[ConcatPart<'_>]) -> Doc {
        Doc::text(format!("self str: {}", st_joined(parts)))
    }

    fn item_call_limitation(&self) -> Option<&'static str> {
        None
    }

    /// `self renderCardTitle: 'Hi' tag: title` (the class side of the same
    /// class: the keyword selector names the callee's parameters), or
    /// `self renderUi` for an item without parameters.
    fn item_call(&self, item: &Ident, params: &[Ident], args: Vec<Doc>, _broken: bool) -> Doc {
        if args.is_empty() {
            return Doc::text(format!("self {}", item.lower_camel()));
        }
        let mut parts = vec![Doc::text("self")];
        for (key, a) in keywords(item, params).into_iter().zip(args) {
            parts.push(Doc::text(format!(" {key}: ")));
            parts.push(a);
        }
        Doc::cat(parts)
    }

    /// A Smalltalk string: a literal, a parameter passed on, or
    /// `'by ' , author` (a binary expression: a keyword argument as is).
    fn native_string(&self, parts: &[ConcatPart<'_>]) -> Doc {
        Doc::text(st_joined(parts))
    }
}

/// A Smalltalk string expression joined from `parts` (`'by ' , author`).
fn st_joined(parts: &[ConcatPart<'_>]) -> String {
    if parts.is_empty() {
        return st_string("");
    }
    parts
        .iter()
        .map(|p| match p {
            ConcatPart::Lit(s) => st_string(s),
            ConcatPart::Param(i) => st_param(i),
        })
        .collect::<Vec<_>>()
        .join(" , ")
}

/// The keywords of the selector of item `name` with parameters `params`,
/// one per parameter (`renderCardTitle`, `text`, ..): the first joins the
/// item's name.
fn keywords<'a>(name: &Ident, params: impl IntoIterator<Item = &'a Ident>) -> Vec<String> {
    let name = name.lower_camel();
    params
        .into_iter()
        .enumerate()
        .map(|(i, p)| {
            if i == 0 {
                format!("{name}{}", capitalize(&p.lower_camel()))
            } else {
                p.lower_camel()
            }
        })
        .collect()
}

/// [`keywords`] of an item's own selector.
fn item_keywords(item: &Item) -> Vec<String> {
    keywords(&item.name, item.params.iter().map(|p| &p.name))
}

/// The keyword selector of an item with parameters, with its parameters
/// (`renderCardTitle: title text: text`).
fn keyword_header(item: &Item) -> String {
    item_keywords(item)
        .iter()
        .zip(&item.params)
        .map(|(key, p)| format!("{key}: {}", st_param(&p.name)))
        .collect::<Vec<_>>()
        .join(" ")
}

/// The unary method of an item with parameters: the keyword method with
/// the component's defaults.
fn defaults_method(item: &Item, class: &str) -> String {
    let name = method_name(item);
    let call = item_keywords(item)
        .iter()
        .zip(&item.params)
        .map(|(key, p)| {
            let value = match &p.default {
                Some(Expr::Str(s)) => st_string(s),
                Some(d) => expr_doc(&Smalltalk, d).flat(),
                None => "nil".to_string(),
            };
            format!("{key}: {value}")
        })
        .collect::<Vec<_>>()
        .join(" ");
    format!(
        "\n\"`{name}` with the component's defaults.\"\n{{ #category : 'ui' }}\n{class} class >> {name} \
         [\n    ^ self {call}\n]\n"
    )
}

/// The app around a DOM module (`m.app`): it builds the UI once (see
/// [`NO_CALLBACKS`]).
fn smalltalk_app_main(m: &Module) -> String {
    let Some(app) = &m.app else {
        return String::new();
    };
    let class = class_name(m);
    let root = if app.is_body {
        format!("{class} {}", app.root.lower_camel())
    } else {
        format!("AzulNative azDomWithChild: AzulNative azDomCreateBody child: ({class} {})", app.root.lower_camel())
    };
    format!(
        "\"{} - generated by AzBuilder (azul-css codegen, Smalltalk).\"\n\"Load \
         target/codegen/Azul.st (Tonel, see BaselineOfAzul.st) and {class}.st into a Pharo image \
         with libazul on the library path, then evaluate this.\"\n\"No window opens: {}. This \
         builds the UI once.\"\n| ui |\nui := {root}.\nTranscript show: {}; cr.\n",
        one_line(&app.title).replace('"', "''"),
        NO_CALLBACKS,
        st_string(&format!("{}: built", one_line(&app.title))),
    )
}

const VEC: &str = "{ #category : 'private' }
AzulStyles class >> vec: aBlock of: aType items: anArray [
    \"Copies the items into an external array; aBlock (the Vec's copyFromPtr) clones them.\"
    | arr result |
    arr := FFIExternalArray externalNewType: aType size: anArray size.
    anArray doWithIndex: [ :each :i | arr at: i put: each ].
    result := aBlock value: arr getHandle value: anArray size.
    arr free.
    ^ result
]
";

const STR: &str = "{ #category : 'private' }
AzulStyles class >> str: aString [
    \"An AzString holding the UTF-8 bytes of aString.\"
    | bytes buf |
    bytes := aString utf8Encoded.
    buf := ExternalAddress allocate: (bytes size max: 1).
    bytes doWithIndex: [ :b :i | buf byteAt: i put: b ].
    ^ [ AzulNative azStringCopyFromBytes: buf start: 0 len: bytes size ] ensure: [ buf free ]
]
";

fn method_name(item: &Item) -> String {
    item.name.lower_camel()
}

/// Item `item` of module `m` as a class-side method of the module's class.
fn item_method(m: &Module, item: &Item) -> (bool, String) {
    let class = class_name(m);
    // one comment per method (Tonel reads a single comment before it)
    let comments = item_comments(&Smalltalk, item);
    let mut out = String::new();
    if !comments.is_empty() {
        out.push_str(&format!("\"{}\"\n", comments.join("\n").replace('"', "''")));
    }
    let name = method_name(item);
    match item_doc(&Smalltalk, item) {
        Ok(doc) if !item.params.is_empty() => {
            out.push_str(&format!(
                "{{ #category : 'ui' }}\n{class} class >> {} [\n    ^ {}\n]\n",
                keyword_header(item),
                render(&doc, "    ", 1)
            ));
            out.push_str(&defaults_method(item, class));
            (true, out)
        }
        Ok(doc) => {
            let category = if item.ty == "Dom" { "ui" } else { "styles" };
            out.push_str(&format!(
                "{{ #category : '{category}' }}\n{class} class >> {name} [\n    ^ {}\n]\n",
                render(&doc, "    ", 1)
            ));
            (true, out)
        }
        Err(reason) => {
            out.push_str(&format!(
                "\"{name}: not expressible with the Smalltalk bindings: {}\"\n",
                reason.replace('"', "''")
            ));
            (false, out)
        }
    }
}

impl CodegenBackend for Smalltalk {
    fn lang(&self) -> &'static str {
        "smalltalk"
    }

    fn aliases(&self) -> &'static [&'static str] {
        &["pharo", "st"]
    }

    fn display_name(&self) -> &'static str {
        "Smalltalk"
    }

    fn extension(&self) -> &'static str {
        "st"
    }

    fn emit_module(&self, m: &Module) -> String {
        let class = class_name(m);
        let category = if m.is_dom() { "Azul-Ui" } else { "Azul-Styles" };
        let mut out = format!(
            "\"Generated by azul-css codegen (Smalltalk). Do not edit by hand.\"\nClass {{\n    \
             #name : '{class}',\n    #superclass : 'Object',\n    #category : \
             '{category}'\n}}\n",
        );
        if module_any(m, &|e| matches!(e, Expr::Vec { .. })) {
            out.push('\n');
            out.push_str(&VEC.replace("AzulStyles", class));
        }
        if module_any(m, &|e| matches!(e, Expr::Str(_) | Expr::Param(_) | Expr::Concat(_))) {
            out.push('\n');
            out.push_str(&STR.replace("AzulStyles", class));
        }
        for item in &m.items {
            out.push('\n');
            out.push_str(&item_method(m, item).1);
        }
        if let Some(lib) = &m.library {
            out.push_str(&format!(
                "\n\"{}\"\n",
                registration_note(lib, NO_CALLBACKS).join("\n").replace('"', "''")
            ));
        }
        out
    }

    fn exports_dom(&self) -> bool {
        true
    }

    fn emit_project_files(&self, m: &Module) -> Vec<GeneratedFile> {
        if m.app.is_some() {
            return vec![
                GeneratedFile {
                    path: "AzulUi.st".to_string(),
                    contents: self.emit_module(m),
                },
                GeneratedFile {
                    path: "main.st".to_string(),
                    contents: smalltalk_app_main(m),
                },
            ];
        }
        let mut main = String::from(
            "\"Load target/codegen/Azul.st (Tonel, see BaselineOfAzul.st) and AzulStyles.st into \
             a Pharo image with libazul on the library path, then evaluate:\"\n",
        );
        for item in m.items.iter().filter(|i| item_method(m, i).0) {
            let name = method_name(item);
            main.push_str(&format!(
                "Transcript show: '{name}: ', AzulStyles {name} len printString, ' \
                 properties'; cr.\n"
            ));
        }
        vec![
            GeneratedFile {
                path: "AzulStyles.st".to_string(),
                contents: self.emit_module(m),
            },
            GeneratedFile {
                path: "main.st".to_string(),
                contents: main,
            },
        ]
    }
}
